PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:The_Melon_Route dbr:Cilvēka_bērns }

  # film label (optional)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director name
  OPTIONAL { ?director rdfs:label ?directorName . FILTER (lang(?directorName) = "en") }

  # director birth date
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
}
LIMIT 100
